<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { api } from '@/app/runtime'; import { useSessionStore } from '@/stores/session';
import { t } from '@/i18n';
const router = useRouter(); const session = useSessionStore(); const form = ref({ username: '', email: '', password: '', code: '' }); const pending = ref(false); const error = ref('');
async function submit() { error.value = ''; try { await api.auth.register({ username: form.value.username, email: form.value.email, password: form.value.password }); pending.value = true; } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } }
async function verify() { error.value = ''; try { const result = await api.auth.registerVerify({ ...form.value }); session.applyUser(result.user as Record<string, unknown> | undefined); await router.replace('/home'); } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } }
</script>
<template><section class="page auth-page"><header class="page-heading"><h1>{{ t('s_1n008jl') }}</h1></header><form class="card form" @submit.prevent="pending ? verify() : submit()"><label>{{ t('s_u9jq8n') }}<input v-model="form.username" required autocomplete="username"></label><label>{{ t('s_185tvls') }}<input v-model="form.email" required type="email" autocomplete="email"></label><label>{{ t('s_1aph6eg') }}<input v-model="form.password" required type="password" autocomplete="new-password"></label><label v-if="pending">{{ t('s_185tvls') }}{{ t('s_s8pbve') }}<input v-model="form.code" required inputmode="numeric"></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="cta">{{ pending ? t('s_1gpj15x') : t('s_shrzdv') }}</button><button type="button" class="text-action" @click="router.back()">{{ t('s_1mxt6kz') }}</button></form></section></template>
